	private boolean potionsDirty;

	@Provides
	UltimateBankTabsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UltimateBankTabsConfig.class);
	}

	@Override
	protected void startUp()
	{
		data = TabData.load(gson);
		// six foods became the default: a stored four is the old default (RuneLite saves defaults), not a choice
		if (configManager.getConfiguration(UltimateBankTabsConfig.GROUP, SIX_FOODS_KEY) == null)
		{
			if (config.foodCount() == 4)
			{
				configManager.setConfiguration(UltimateBankTabsConfig.GROUP, "foodCount", 6);
			}
			configManager.setConfiguration(UltimateBankTabsConfig.GROUP, SIX_FOODS_KEY, true);
		}
		builder = new TabBuilder(data, id -> EquipStats.of(itemManager.getItemStats(id)), this::heals,
			id -> itemManager.getItemComposition(id).getName());
		writer = new BankTagsWriter(configManager, tagManager, layoutManager, bankTagsService, itemManager::canonicalize);
		writer.restore(data.tabs.stream().map(t -> t.key).collect(Collectors.toList()));
		// what Bank Tags holds now (the bank may be open); BANKMAIN_INIT refreshes it on every bank open
		writer.bankHolds(new ArrayList<>(tabManager.getTabs()));
		writer.reserve(replacedTabs().stream().map(t -> t.name).collect(Collectors.toList()));
		skillIcons = new SkillIcons(client);
		accepted = Boolean.parseBoolean(configManager.getConfiguration(UltimateBankTabsConfig.GROUP, ACCEPTED_KEY));
		overlayManager.add(reasonOverlay);
		BankTagsWriter w = writer;
		clientThread.invokeLater(() ->
		{
			bankOpen = client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
			if (!accepted)
			{
				askToReplace(w);
				return;
			}
			// a restore asked for first cancels a replacement still waiting for the bank
			if (!bankOpen && config.restoreTabs())
			{
				restoreReplaced(false);
			}
			if (!bankOpen)
			{
				replacePending();
			}
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadSnapshot();
				slayerTask = SlayerTask.read(client);
				rebuild(false);
			}
		});
	}

	/**
	 * First start, when the bank has tabs this plugin didn't make: the player chooses to replace them all
	 * (backed up), keep them (by default replacing just the ones named like one of ours, so there aren't two
	 * Slayer tabs), or turn the plugin back off.
	 */
	private void askToReplace(BankTagsWriter w)
	{
		List<String> others = w.otherTabs();
		if (others.isEmpty())
		{
			accept(w, others);
			return;
		}
		// only tabs this plugin will show: a tab of ours switched off leaves theirs nothing to clash with
		List<String> sameNamed = BankTagsWriter.sameNamed(others,
			data.tabs.stream().filter(t -> enabled(t.key)).map(t -> t.name).collect(Collectors.toList()));
		List<String> conflicts = conflicts();
		StringBuilder msg = new StringBuilder("<html><body style='width: 360px'>")
			.append("<b>BiS Bank Tabs adds its own bank tabs.</b> You have ").append(others.size())
			.append(others.size() == 1 ? " tab" : " tabs").append(" already: <i>")
			.append(others.stream().limit(12).collect(Collectors.joining(", ")))
			.append(others.size() > 12 ? ", ..." : "").append("</i><br><br>")
			.append("<b>Replace all my tabs</b> removes them, so the bank holds just this plugin's tabs.<br>")
			.append("<b>Keep my tabs</b> leaves them, with this plugin's tabs after them.<br><br>")
			.append("Removed tabs are backed up, and their items keep their tags, so tag: searches still work.")
			.append(" <b>Bring back replaced tabs</b> in this plugin's settings puts them back.");
		if (!conflicts.isEmpty())
		{
			msg.append("<br><br><b>Also on:</b> ").append(String.join("; ", conflicts))
				.append(". Turn ").append(conflicts.size() == 1 ? "it" : "them").append(" off so it doesn't fight over your tabs.");
		}
		msg.append("</body></html>");
		JCheckBox replaceSameNamed = new JCheckBox("<html><body style='width: 340px'>When keeping, replace the "
			+ (sameNamed.size() == 1 ? "one" : sameNamed.size()) + " named like a tab of this plugin's: <i>"
			+ String.join(", ", sameNamed) + "</i></body></html>", true);
		Object message = sameNamed.isEmpty() ? msg.toString() : new Object[]{msg.toString(), replaceSameNamed};
		String[] options = {"Replace all my tabs", "Keep my tabs", "Turn plugin off"};
		SwingUtilities.invokeLater(() ->
		{
			// owned by the game window so it can't open behind it; keeping is the default
			int choice = JOptionPane.showOptionDialog(client.getCanvas(), message, "BiS Bank Tabs",
				JOptionPane.YES_NO_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
			if (choice == 0)
			{
				clientThread.invokeLater(() -> accept(w, others));
			}
			else if (choice == 1)
			{
				List<String> replace = replaceSameNamed.isSelected() ? sameNamed : Collections.emptyList();
				clientThread.invokeLater(() -> accept(w, replace));
			}
			else if (writer == w)
			{
				turnOff();
			}
		});
	}

	/** @param agreed the player's tabs the question listed: only these are replaced */
	private void accept(BankTagsWriter w, List<String> agreed)
	{
		if (writer != w)
		{
			// turned off while the question was open
			return;
		}
		configManager.setConfiguration(UltimateBankTabsConfig.GROUP, ACCEPTED_KEY, true);
		accepted = true;
		bankOpen = client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
		if (agreed.isEmpty())
		{
			// nothing of theirs to replace
		}
		else if (bankOpen)
		{
			// Bank Tags holds the open bank's tab list and would write the old tabs back: finish on the next open
			configManager.setConfiguration(UltimateBankTabsConfig.GROUP, REPLACE_PENDING_KEY, Text.toCSV(agreed));
			chat("BiS Bank Tabs: close your bank and open it again to finish replacing " + tabsNamed(agreed) + ".");
		}
		else
		{
			replaceNow(agreed);
		}
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadSnapshot();
			rebuild(false);
		}
		if (bankOpen && agreed.isEmpty())
		{
			// Bank Tags loaded this bank's tab list before ours existed: they show from the next open
			chat("BiS Bank Tabs: close your bank and open it again to see its tabs.");
		}
	}

	/** "your Slayer tab", "your Slayer, Mining tabs", "your 7 bank tabs" */
	private static String tabsNamed(List<String> names)
	{
		return names.size() == 1 ? "your " + names.get(0) + " tab"
			: names.size() <= 3 ? "your " + String.join(", ", names) + " tabs"
			: "your " + names.size() + " bank tabs";
	}

	/** A takeover the player agreed to with the bank open, done now (Bank Tags is between bank opens). */
	private void replacePending()
	{
		String pending = configManager.getConfiguration(UltimateBankTabsConfig.GROUP, REPLACE_PENDING_KEY);
		if (pending != null && !pending.isEmpty())
		{
			// "true": stored before the agreed tabs were kept, meaning all of them
			replaceNow("true".equals(pending) ? null : Text.fromCSV(pending));
		}
	}

	/** Take the player's own tabs out (backed up), now that Bank Tags isn't holding an open bank's list. */
	private void replaceNow(List<String> agreed)
	{
		configManager.unsetConfiguration(UltimateBankTabsConfig.GROUP, REPLACE_PENDING_KEY);
		List<BankTagsWriter.SavedTab> saved = writer.replaceOthers(agreed);
		if (!saved.isEmpty())
		{
			List<BankTagsWriter.SavedTab> all = replacedTabs();
			all.addAll(saved);
			configManager.setConfiguration(UltimateBankTabsConfig.GROUP, REPLACED_KEY, gson.toJson(all, SAVED_TABS));
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				chat("BiS Bank Tabs: replaced " + tabsNamed(saved.stream().map(t -> t.name).collect(Collectors.toList()))
					+ ". Bring back replaced tabs in the plugin settings puts " + (saved.size() == 1 ? "it" : "them") + " back.");
			}
		}
	}

	private void turnOff()
	{
		pluginManager.setPluginEnabled(this, false);
		try
		{
			pluginManager.stopPlugin(this);
		}
		catch (PluginInstantiationException e)
		{
			log.warn("could not turn BiS Bank Tabs off", e);
		}
	}

	private List<BankTagsWriter.SavedTab> replacedTabs()
	{
		String json = configManager.getConfiguration(UltimateBankTabsConfig.GROUP, REPLACED_KEY);
		List<BankTagsWriter.SavedTab> tabs = json == null || json.isEmpty() ? null : gson.fromJson(json, SAVED_TABS);
		return tabs == null ? new ArrayList<>() : new ArrayList<>(tabs);
	}

	/** "Bring back replaced tabs": put the player's old tabs back next to ours. */
	private void restoreReplaced(boolean atBankInit)
	{
		if (writer == null)
		{
			return;
		}
		if (bankOpen && !atBankInit)
		{
			// Bank Tags holds the open bank's tab list and would write it back over the restored tabs; the
			// setting stays on until the next bank open does it
			chat("BiS Bank Tabs: close your bank and open it again to bring back your replaced tabs.");
			return;
		}
		// a replacement still waiting for the bank is called off: those tabs never leave
		String pending = configManager.getConfiguration(UltimateBankTabsConfig.GROUP, REPLACE_PENDING_KEY);
		boolean cancelled = pending != null && !pending.isEmpty();
		configManager.unsetConfiguration(UltimateBankTabsConfig.GROUP, REPLACE_PENDING_KEY);
		List<BankTagsWriter.SavedTab> saved = replacedTabs();
		writer.restoreOthers(saved);
		configManager.unsetConfiguration(UltimateBankTabsConfig.GROUP, REPLACED_KEY);
		configManager.setConfiguration(UltimateBankTabsConfig.GROUP, RESTORE_KEY, false);
		chat(!saved.isEmpty() ? "BiS Bank Tabs: brought back " + tabsNamed(saved.stream().map(t -> t.name)
			.collect(Collectors.toList())) + "." + (atBankInit ? "" : " Open your bank to see them.")
			: cancelled ? "BiS Bank Tabs: kept your tabs; none will be replaced."
			: "BiS Bank Tabs: there are no replaced tabs to bring back.");
	}

	/** Enabled plugins that fight over the same tabs, as "Name (what it does)". */
	private List<String> conflicts()
	{
		List<String> found = new ArrayList<>();
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin == this || !pluginManager.isPluginEnabled(plugin))
			{
				continue;
			}
			String internal = ExternalPluginManager.getInternalName(plugin.getClass());
			PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			String name = descriptor == null ? null : descriptor.name();
			for (String[] c : CONFLICTS)
			{
				if (c[0].equals(internal) || c[1].equalsIgnoreCase(name))
				{
					found.add(c[1] + " (" + c[2] + ")");
				}
			}
		}
		return found;
	}

	private void warnConflicts()
	{
		for (String conflict : conflicts())
		{
			if (warned.add(conflict))
			{
				chat("BiS Bank Tabs: " + conflict + " is also on. Turn one of them off so they don't fight over"
					+ " your bank tabs.");
			}
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(reasonOverlay);
		reasons = new HashMap<>();
		tabSprites = new HashMap<>();
		warned.clear();
		BankTagsWriter w = writer;
		boolean remove = config.removeOnStop();
		clientThread.invokeLater(() ->
		{
			if (remove)
			{
				w.removeAll();
			}
			else
			{
				w.unregisterAll();
			}
		});
		// an open "replace your tabs?" question checks this before acting
		writer = null;
		accepted = false;
		stored = new HashSet<>();
		potions = new HashSet<>();
		bankOpen = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadSnapshot();
			dirty = true;
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			stored = new HashSet<>();
			potions = new HashSet<>();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			// the server sends the task again after logging in
			slayerTask = null;
		}
	}

	/** A new slayer task (or none): the Slayer tab follows it. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.IRONMAN && event.getValue() != accountType && accountType != -1)
		{
			// the account type arrived after the first build (or a group ironman left the group): cheaper picks follow
			dirty = true;
		}
		if (SlayerTask.affects(event.getVarpId(), event.getVarbitId()))
		{
			// later, so every value of the same server update has landed (as the core Slayer plugin does)
			clientThread.invokeLater(() ->
			{
				SlayerTask now = SlayerTask.read(client);
				if (!Objects.equals(now, slayerTask))
				{
					slayerTask = now;
					dirty = true;
				}
			});
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
			potionsDirty = true;
			dirty = true;
			if (accepted)
			{
				warnConflicts();
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			bankOpen = false;
		}
	}

	/**
	 * Bank Tags loads its tab list when the bank opens. Running first (higher
	 * priority) lets tabs that just became non-empty show up in this same open.
	 */
	@Subscribe(priority = 1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_INIT)
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank != null)
			{
				readBank(bank);
				// tabs added here are picked up by this very bank open, so no "reopen" hint
				rebuild(false);
			}
			// a restore asked for first cancels a replacement still waiting for this open
			if (writer != null && config.restoreTabs())
			{
				restoreReplaced(true);
			}
			if (writer != null && accepted)
			{
				replacePending();
			}
			if (writer != null)
			{
				// Bank Tags loads the tab list right after this
				writer.bankOpened();
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			readBank(event.getItemContainer());
			potionsDirty = true;
			dirty = true;
		}
		else if ((id == InventoryID.INV || id == InventoryID.WORN) && (bankOpen || config.countCarried()))
		{
			// potions moved between the inventory and potion storage show up here too
			potionsDirty |= bankOpen;
			dirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (potionsDirty && bankOpen)
		{
			potionsDirty = false;
			readPotionStorage();
		}
		if (dirty)
		{
			rebuild(bankOpen);
		}
	}

	/**
	 * Bank Tags' Remove-tag can't take an item the plugin shows out of these tabs (the plugin decides what they
	 * hold), but it does take it out of the layout, after which Bank Tags drops it in the first empty cell for
	 * good. An item the player dragged onto the tab themselves keeps it, so they can take it back out.
	 */
	@Subscribe(priority = -1)
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Bank Tags adds Remove-tag with createMenuEntry, which posts no event of its own, right after the game's
		// Examine (Withdraw-All-but-1 in potion storage), so strip it on that entry's event
		String option = event.getOption();
		String tag = bankTagsService.getActiveTag();
		if (writer == null || !("Examine".equals(option) || "Withdraw-All-but-1".equals(option))
			|| writer.keyOf(tag) == null)
		{
			return;
		}
		int itemId = event.getMenuEntry().getItemId();
		if (itemId > 0 && !writer.shows(tag, itemId))
		{
			return;
		}
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			if (entry.getOption().startsWith("Remove-tag"))
			{
				client.getMenu().removeMenuEntry(entry);
			}
		}
		String key = writer.keyOf(tag);
		if (itemId > 0 && (ALCH_TAB.equals(key) || JUNK_TAB.equals(key)))
		{
			// just above Examine, like Bank Tags' own Remove-tag
			int item = itemManager.canonicalize(itemId);
			boolean alch = ALCH_TAB.equals(key);
			client.getMenu().createMenuEntry(-1)
				.setOption(alch ? REMOVE_ALCH : NOT_JUNK)
				.setTarget(event.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(e ->
				{
					if (alch)
					{
						removeAlch(item);
					}
					else
					{
						notJunk(item);
					}
				});
		}
	}

	/** what you do with an item you keep: open it for what's inside, or teleport with it */
	private static final Set<String> USE_ACTIONS = new HashSet<>(Arrays.asList(
		"open", "search", "loot", "rub", "break", "read", "teleport"));

	/**
	 * Kept for what you do with it: opened for what's inside (a bird nest's Search, a casket's Open, an impling
	 * jar's Loot) or a teleport (jewellery you Rub, a tablet you Break, a scroll you Read).
	 */
	private static boolean forUse(String[] actions)
	{
		if (actions != null)
		{
			for (String a : actions)
			{
				if (a != null && USE_ACTIONS.contains(a.toLowerCase()))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** what you do with an item you keep that the Junk tab respects: open it, teleport with it, fill it */
	private static final Set<String> KEEP_ACTIONS = new HashSet<>(Arrays.asList(
		"open", "search", "loot", "rub", "break", "teleport", "fill", "check"));

	/** Kept for what you do with it: a casket you open, jewellery you rub, a sack you fill. Books you read aren't. */
	private static boolean keptForUse(String[] actions)
	{
		if (actions != null)
		{
			for (String a : actions)
			{
				if (a != null && KEEP_ACTIONS.contains(a.toLowerCase()))
				{
					return true;
				}
			}
		}
		return false;
	}

