		assertEquals("their swap moved down under the block", 31, next[ROW5]);
		assertEquals(30, next[ROW5 + 1]);
		assertEquals(40, next[ROW5 + W]);
	}

	@Test
	public void aNewSectionDoesNotShareARowOpenedForAnotherSection()
	{
