	@Test
	public void aNewHerbKeepsOneColumnDownItsBand()
	{
		int[] previous = layout(ROW5 + W + 2, ROW5, 249, ROW5 + 1, 253, ROW5 + 2, 255, ROW5 + 3, 257,
			ROW5 + W, 91, ROW5 + W + 1, 95);
		int[] saved = layout(ROW5 + W + 2, ROW5, 253, ROW5 + 1, 249, ROW5 + 2, 255, ROW5 + 3, 257,
			ROW5 + W, 91, ROW5 + W + 1, 95);
		// marrentill (clean 251, unfinished 93) slots in as the second herb
		int[] planned = layout(ROW5 + W + 3, ROW5, 249, ROW5 + 1, 251, ROW5 + 2, 253, ROW5 + 3, 255, ROW5 + 4, 257,
			ROW5 + W, 91, ROW5 + W + 1, 93, ROW5 + W + 2, 95);
		int[] next = next(saved, previous, planned, rows(7, 5, "herbs_clean#0", "herbs_unf#0"), Collections.emptySet());
		assertEquals("clean and unfinished in one column", pos(next, 251) % W, pos(next, 93) % W);
	}

	@Test
	public void aNewOutfitPieceJoinsItsOwnOutfitsRow()
	{
		// two outfits in a sets section: A (60..65) on one row, B (70..72) on the next; they swapped two of A
		int[] previous = layout(ROW5 + W + 3, ROW5, 60, ROW5 + 1, 61, ROW5 + 2, 62, ROW5 + 3, 63, ROW5 + 4, 64,
			ROW5 + 5, 65, ROW5 + W, 70, ROW5 + W + 1, 71, ROW5 + W + 2, 72);
		int[] saved = previous.clone();
		saved[ROW5] = 61;
		saved[ROW5 + 1] = 60;
		int[] planned = layout(ROW5 + W + 4, ROW5, 60, ROW5 + 1, 61, ROW5 + 2, 62, ROW5 + 3, 63, ROW5 + 4, 64,
			ROW5 + 5, 65, ROW5 + W, 73, ROW5 + W + 1, 70, ROW5 + W + 2, 71, ROW5 + W + 3, 72);
		int[] next = next(saved, previous, planned, rows(7, 5, "graceful", "graceful"), Collections.emptySet());
		assertEquals("B's new hood goes in B's row", 6, pos(next, 73) / W);
	}

	@Test
	public void anAltAccountRoundTripKeepsTheirArrangement()
	{
		Map<Integer, Integer> home = new HashMap<>();
		Set<Integer> bis = new HashSet<>(Arrays.asList(HEAD));
		// main: gear block, tools, bait, a blank row, raw fish
		int[] main = layout(8 * W + 1, HEAD, 10, ROW5, 307, ROW5 + 1, 309, ROW5 + 2, 303, ROW5 + 3, 301,
			ROW5 + W, 313, ROW5 + W + 1, 314, 8 * W, 317);
		String[] mainRows = rows(9, 0, "block", null, null, null, null, "gear", "bait", null, "goods");
		int[] saved = main.clone();
		// they reversed the tools
		saved[ROW5] = 301;
		saved[ROW5 + 1] = 303;
		saved[ROW5 + 2] = 309;
		saved[ROW5 + 3] = 307;
		// an alt with only the raw fish: no block
		int[] alt = layout(1, 0, 317);
		int[] onAlt = LayoutMerger.next(saved, main, alt, rows(1, 0, "goods"), Collections.emptySet(), false, true,
			id -> id, home);
		int[] back = LayoutMerger.next(onAlt, alt, main, mainRows, bis, true, false, id -> id, home);
		int tools = pos(back, 301);
		assertEquals("their tool order is back", 303, back[tools + 1]);
		assertEquals(309, back[tools + 2]);
		assertEquals(307, back[tools + 3]);
		assertEquals(10, back[HEAD]);
	}

	@Test
	public void twoNewSectionsKeepTheBlankRowBeforeTheBottom()
	{
		int[] previous = layout(7 * W + 1, ROW5, 30, ROW5 + 1, 31, 7 * W, 90);
		int[] saved = layout(7 * W + 1, ROW5, 31, ROW5 + 1, 30, 7 * W, 90);
		// blighted supplies and spell sacks arrive together, above the enchanting row
		int[] planned = layout(10 * W + 1, ROW5, 30, ROW5 + 1, 31, 7 * W, 80, 8 * W, 85, 10 * W, 90);
		int[] next = next(saved, previous, planned,
			rows(11, 5, "food", null, "blighted", "blighted_sacks", null, "enchanting"), Collections.emptySet());
		int sacks = pos(next, 85) / W;
		assertEquals("the sacks right under the blighted row", pos(next, 80) / W + 1, sacks);
		assertEquals("still a blank row before the enchanting row", sacks + 2, pos(next, 90) / W);
	}

	@Test
	public void aNewHerbDoesNotTakeAnotherHerbsColumn()
	{
		// gear row (swapped), then grimy herbs (guam, ranarr) over clean herbs (guam, tarromin, harralander, ranarr)
		int[] previous = layout(7 * W + 4, ROW5, 60, ROW5 + 1, 61, 6 * W, 199, 6 * W + 3, 207,
			7 * W, 249, 7 * W + 1, 253, 7 * W + 2, 255, 7 * W + 3, 257);
		int[] saved = previous.clone();
		saved[ROW5] = 61;
		saved[ROW5 + 1] = 60;
		// marrentill (grimy 201, clean 251) becomes the second herb column
		int[] planned = layout(7 * W + 5, ROW5, 60, ROW5 + 1, 61, 6 * W, 199, 6 * W + 1, 201, 6 * W + 4, 207,
			7 * W, 249, 7 * W + 1, 251, 7 * W + 2, 253, 7 * W + 3, 255, 7 * W + 4, 257);
		int[] next = next(saved, previous, planned, rows(8, 5, "gear", "herbs_grimy#0", "herbs_clean#0"),
			Collections.emptySet());
		assertEquals("grimy and clean marrentill in one column", pos(next, 201) % W, pos(next, 251) % W);
	}

	@Test
	public void aBlockThatComesAndGoesLeavesTheirArrangementAsItWas()
	{
		Map<Integer, Integer> home = new HashMap<>();
		int weapon = 2 * W;
		int shield = 2 * W + 2;
		Set<Integer> bis = new HashSet<>(Arrays.asList(HEAD, weapon, shield));
		// no slayer task: helmet, shield and hammer in the gear row, food under it
		int[] none = layout(W + 1, 0, 100, 1, 101, 2, 102, W, 200);
		String[] noneRows = rows(2, 0, "gear", "food");
		// on task: helmet and shield in the block with the whip, the hammer and food below
		int[] task = layout(ROW5 + W + 1, HEAD, 100, weapon, 103, shield, 101, ROW5, 102, ROW5 + W, 200);
		String[] taskRows = rows(7, 0, "block", null, null, null, null, "gear", "food");
		int[] saved = none.clone();
		// they swapped the helmet and the shield
		saved[0] = 101;
		saved[1] = 100;
		int[] theirs = saved.clone();
		for (int round = 0; round < 3; round++)
		{
			int[] on = LayoutMerger.next(saved, none, task, taskRows, bis, true, false, id -> id, home);
			assertEquals(100, on[HEAD]);
			assertEquals(101, on[shield]);
			saved = LayoutMerger.next(on, task, none, noneRows, Collections.emptySet(), false, true, id -> id, home);
			assertArrayEquals("after task " + (round + 1), theirs, saved);
		}
	}

	@Test
	public void noGearBlockMeansNoReservedCells()
	{
		int[] previous = layout(2, 0, 30, 1, 31);
		int[] saved = layout(2, 0, 31, 1, 30);
		int[] planned = layout(3, 0, 30, 1, 31, 2, 32);
		assertArrayEquals(new int[]{31, 30, 32},
			LayoutMerger.next(saved, previous, planned, Collections.emptySet()));
	}
}

package com.ultimatebanktabs;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class LayoutPlannerTest
{
	private static final int W = LayoutPlanner.WIDTH;

	private static TabBuilder.Placement p(int id, String slot, String group)
	{
		return new TabBuilder.Placement(id, slot, group, null);
	}

	private static TabBuilder.Section s(String key, String layout, TabBuilder.Placement... items)
	{
		return new TabBuilder.Section(key, key, layout, Arrays.asList(items));
	}

	private static int[] plan(TabBuilder.Section... sections)
	{
		return LayoutPlanner.plan(new TabBuilder.Built(null, Arrays.asList(sections), -1), false);
	}

	private static int at(int[] layout, int row, int col)
	{
		int pos = row * W + col;
		return pos < layout.length ? layout[pos] : -1;
	}

	@Test
	public void equipmentDiagram()
	{
		int[] layout = plan(s("main", "equipment",
			p(1, "HEAD", "head"), p(2, "CAPE", "cape"), p(3, "AMULET", "neck"), p(4, "AMMO", "ammo"),
			p(5, "WEAPON", "weapon"), p(6, "BODY", "body"), p(7, "SHIELD", "shield"), p(8, "LEGS", "legs"),
			p(9, "GLOVES", "hands"), p(10, "BOOTS", "feet"), p(11, "RING", "ring")));
		assertEquals(1, at(layout, 0, 1));
		assertEquals(2, at(layout, 1, 0));
		assertEquals(3, at(layout, 1, 1));
		assertEquals(4, at(layout, 1, 2));
		assertEquals(5, at(layout, 2, 0));
		assertEquals(6, at(layout, 2, 1));
		assertEquals(7, at(layout, 2, 2));
		assertEquals(8, at(layout, 3, 1));
		assertEquals(9, at(layout, 4, 0));
		assertEquals(10, at(layout, 4, 1));
		assertEquals(11, at(layout, 4, 2));
		assertEquals(-1, at(layout, 0, 0));
		assertEquals(-1, at(layout, 2, 3));
	}

	@Test
	public void setsLineUpInOneAlternativesColumn()
	{
		int[] layout = plan(
			s("main", "equipment", p(1, "HEAD", "head"), p(5, "WEAPON", "weapon")),
			s("situational", "alts", p(20, "HEAD", "slayer_helm"), p(21, "AMULET", "salve"),
				p(30, "HEAD", "inquisitor"), p(31, "BODY", "inquisitor"), p(32, "LEGS", "inquisitor")));
		assertEquals(20, at(layout, 0, 4));
		assertEquals(21, at(layout, 1, 4));
		// row 0 col 4 is taken by the slayer helm, so the whole set moves to col 5
		assertEquals(30, at(layout, 0, 5));
		assertEquals(31, at(layout, 2, 5));
		assertEquals(32, at(layout, 3, 5));
	}

	@Test
	public void aSetSharingRowsMirrorsTheEquipmentScreen()
	{
		int[] layout = plan(
			s("main", "equipment", p(1, "HEAD", "head"), p(2, "CAPE", "cape")),
			s("situational", "alts", p(20, "HEAD", "slayer_helm"), p(21, "AMULET", "salve"),
				p(40, "HEAD", "prayer"), p(41, "CAPE", "prayer"), p(42, "AMULET", "prayer"), p(43, "AMMO", "prayer"),
				p(44, "BODY", "prayer"), p(45, "SHIELD", "prayer"), p(46, "BOOTS", "prayer"),
				p(30, "HEAD", "inquisitor"), p(31, "BODY", "inquisitor")));
		// the prayer set's own equipment screen comes first, right beside the best-in-slot one
		assertEquals(40, at(layout, 0, 5));
		assertEquals("the cape sits where a cape goes", 41, at(layout, 1, 4));
		assertEquals(42, at(layout, 1, 5));
		assertEquals("the blessing sits where ammo goes", 43, at(layout, 1, 6));
		assertEquals(44, at(layout, 2, 5));
		assertEquals(45, at(layout, 2, 6));
		assertEquals(46, at(layout, 4, 5));
		assertEquals("its empty cells stay empty", -1, at(layout, 0, 4));
		assertEquals("single pieces take the column after it", 20, at(layout, 0, 7));
		assertEquals(21, at(layout, 1, 7));
	}

	@Test
	public void rowSectionsStartBelowTheBlockOnFreshRows()
	{
		TabBuilder.Placement[] weapons = new TabBuilder.Placement[10];
		for (int i = 0; i < weapons.length; i++)
		{
			weapons[i] = p(100 + i, null, "w");
		}
		int[] layout = plan(
			s("main", "equipment", p(1, "HEAD", "head")),
			s("weapons", "rows", weapons),
			s("supplies", "rows", p(200, null, "boost")));
		assertEquals(100, at(layout, 5, 0));
		assertEquals(107, at(layout, 5, 7));
		assertEquals(108, at(layout, 6, 0));
		assertEquals(109, at(layout, 6, 1));
		assertEquals(-1, at(layout, 6, 2));
		assertEquals(200, at(layout, 7, 0));
	}

	@Test
	public void rowsOnlyTabStartsAtTop()
	{
		int[] layout = plan(s("gear", "rows", p(1, null, "a"), p(2, null, "b")), s("logs", "rows", p(3, null, "c")));
		assertArrayEquals(new int[]{1, 2, -1, -1, -1, -1, -1, -1, 3}, layout);
	}

	@Test
	public void gapRows()
	{
		List<TabBuilder.Section> sections = Arrays.asList(
			s("gear", "rows", p(1, null, "a")), s("logs", "rows", p(3, null, "c")));
		int[] layout = LayoutPlanner.plan(new TabBuilder.Built(null, sections, -1), true);
		assertEquals(3, at(layout, 2, 0));
	}

	@Test
	public void overflowingAlternativesGetTheirOwnRow()
	{
		TabBuilder.Section alts = s("situational", "alts",
			p(20, "HEAD", "a"), p(21, "HEAD", "b"), p(22, "HEAD", "c"), p(23, "HEAD", "d"), p(24, "HEAD", "e"));
		int[] layout = plan(s("main", "equipment", p(1, "HEAD", "head")), alts);
		assertEquals(23, at(layout, 0, 7));
		assertEquals(24, at(layout, 5, 0));
	}

	@Test
	public void outfitsDoNotStraddleRows()
	{
		TabBuilder.Placement[] items = {
			p(1, null, "a"), p(2, null, "a"), p(3, null, "a"), p(4, null, "a"), p(5, null, "a"),
			p(6, null, "b"), p(7, null, "b"), p(8, null, "b"), p(9, null, "b"),
			p(10, null, "c"),
		};
		int[] layout = plan(s("cosmetics", "sets", items));
		assertEquals(5, at(layout, 0, 4));
		assertEquals("set b moves to a fresh row", -1, at(layout, 0, 5));
		assertEquals(6, at(layout, 1, 0));
		assertEquals("a lone item packs in after", 10, at(layout, 1, 4));
	}

	@Test
	public void herbChainsGetARowPerHerb()
	{
		List<String> herbs = Arrays.asList("guam", "marrentill", "tarromin");
		int[] layout = plan(
			new TabBuilder.Section("grimy", "Grimy", "columns", Arrays.asList(p(1, null, "tarromin")), herbs),
			new TabBuilder.Section("clean", "Clean", "columns", Arrays.asList(p(2, null, "guam"), p(3, null, "tarromin")), herbs));
		// marrentill has nothing, so it gets no row; grimy is column 0, clean column 1
		assertEquals(-1, at(layout, 0, 0));
		assertEquals(2, at(layout, 0, 1));
		assertEquals(1, at(layout, 1, 0));
		assertEquals(3, at(layout, 1, 1));
	}

	@Test
	public void eachPotionDoseHasItsOwnColumn()
	{
		List<String> herbs = Arrays.asList("h0", "h1");
		int[] layout = plan(
			new TabBuilder.Section("grimy", "Grimy", "columns", Arrays.asList(p(1, null, "h0")), herbs),
			new TabBuilder.Section("clean", "Clean", "columns", Arrays.asList(p(2, null, "h0"), p(12, null, "h1")), herbs),
			new TabBuilder.Section("sec", "Secondaries", "columns", Arrays.asList(), herbs),
			new TabBuilder.Section("unf", "Unfinished", "columns", Arrays.asList(p(14, null, "h1")), herbs),
			new TabBuilder.Section("potion", "Potions", "columns", Arrays.asList(new TabBuilder.Placement(50, null, "h0", null, 0),
				new TabBuilder.Placement(52, null, "h0", null, 2), new TabBuilder.Placement(63, null, "h1", null, 3)), herbs),
			s("after", "rows", p(999, null, "x")));
		assertEquals(1, at(layout, 0, 0));
		assertEquals(2, at(layout, 0, 1));
		assertEquals("4-dose in column 4", 50, at(layout, 0, 4));
		assertEquals("2-dose in column 6", 52, at(layout, 0, 6));
		assertEquals("the secondary column stays even when empty", 14, at(layout, 1, 3));
		assertEquals("1-dose in column 7", 63, at(layout, 1, 7));
		assertEquals(999, at(layout, 2, 0));
	}

	@Test
	public void finishedGoodsAfterABlankRow()
	{
		int[] layout = plan(s("gear", "rows", p(1, null, "a")), s("goods_logs", "goods", p(2, null, "b")),
			s("goods_nests", "goods", p(3, null, "c")));
		assertEquals(1, at(layout, 0, 0));
		assertEquals("blank separator row", -1, at(layout, 1, 0));
		assertEquals(2, at(layout, 2, 0));
		assertEquals("later goods groups just start a new row", 3, at(layout, 3, 0));
	}

	@Test
	public void bottomSectionsSeparateAndKeepGroups()
	{
		int[] layout = plan(s("runes", "rows", p(1, null, "r")),
			s("enchanting", "bottom", p(10, null, "opal"), p(11, null, "opal"), p(12, null, "opal"), p(13, null, "opal"),
				p(20, null, "sapphire"), p(21, null, "sapphire"), p(22, null, "sapphire"), p(23, null, "sapphire"),
				p(30, null, "jade")));
		assert at(layout, 1, 0) == -1 : "blank row before the bottom section";
		assertEquals(10, at(layout, 2, 0));
		assertEquals("two gems to a row", 23, at(layout, 2, 7));
		assertEquals(30, at(layout, 3, 0));
	}

	@Test
	public void separateSectionStandsApartAboveTheBottom()
	{
		TabBuilder.Section[] sections = {s("supplies", "rows", p(1, null, "food")),
			s("blighted", "separate", p(2, null, "food"), p(3, null, "food")),
			s("blighted_sacks", "separate", p(7, null, "sacks"), p(8, null, "sacks")),
			s("enchanting", "bottom", p(11, null, "opal"))};
		int[] layout = plan(sections);
		assertEquals(1, at(layout, 0, 0));
		assertEquals("blank row before the blighted section", -1, at(layout, 1, 0));
		assertEquals(2, at(layout, 2, 0));
		assertEquals("the next separate section follows on its own row, no blank between", 7, at(layout, 3, 0));
		assertEquals("the bottom keeps its own blank row", -1, at(layout, 4, 0));
		assertEquals(11, at(layout, 5, 0));
		int[] gaps = LayoutPlanner.plan(new TabBuilder.Built(null, Arrays.asList(sections), -1), true);
		assertEquals("one blank row, not two, with gap rows on", 2, at(gaps, 2, 0));
	}

	@Test
	public void emptyTab()
	{
		assertEquals(0, plan(new TabBuilder.Section("x", "x", "rows", Collections.emptyList())).length);
	}
}

package com.ultimatebanktabs;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.BeforeClass;
import org.junit.Test;

public class TabBuilderTest
{
	private static TabData data;
	private static TabBuilder builder;
	private static Map<String, List<Integer>> ids;
	private static final Map<Integer, EquipStats> STATS = new HashMap<>();

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = new Gson();
		data = TabData.load(gson);
		try (Reader r = new InputStreamReader(TabBuilderTest.class.getResourceAsStream("fixture.json"), StandardCharsets.UTF_8))
		{
			Fixture f = gson.fromJson(r, new TypeToken<Fixture>()
			{
			}.getType());
			ids = f.items;
			f.stats.forEach((id, v) -> STATS.put(Integer.parseInt(id), new EquipStats((int) v[0], (int) v[1],
				(int) v[2], (int) v[3], (int) v[4], (int) v[5], (int) v[6], (int) v[7], (int) v[8], v[9], (int) v[10],
				(int) v[11], v[12], v.length > 13 && v[13] > 0)));
		}
		builder = new TabBuilder(data, STATS::get);
	}

	static class Fixture
	{
		Map<String, List<Integer>> items;
		Map<String, double[]> stats;
	}

	static int id(String name)
	{
		List<Integer> list = ids.get(name);
		assertNotNull("not in fixture: " + name, list);
		return list.get(0);
	}

	static Set<Integer> own(String... names)
	{
		return Arrays.stream(names).map(TabBuilderTest::id).collect(Collectors.toSet());
	}

	static TabData.Tab tab(String key)
	{
		return data.tabs.stream().filter(t -> t.key.equals(key)).findFirst().orElseThrow(IllegalStateException::new);
	}

	static TabBuilder.Built build(String tab, Set<Integer> owned)
	{
		return builder.build(tab(tab), owned, new TabBuilder.Options());
	}

	static TabBuilder.Section section(TabBuilder.Built built, String key)
	{
		return built.getSections().stream().filter(s -> s.getKey().equals(key)).findFirst().orElseThrow(IllegalStateException::new);
	}

	static Map<String, Integer> bySlot(TabBuilder.Section s)
	{
		Map<String, Integer> m = new HashMap<>();
		s.getItems().forEach(p -> m.putIfAbsent(p.getSlot(), p.getItemId()));
		return m;
	}

	static Set<Integer> items(TabBuilder.Section s)
	{
		return s.getItems().stream().map(TabBuilder.Placement::getItemId).collect(Collectors.toSet());
	}

	static List<Integer> order(TabBuilder.Section s)
	{
		return s.getItems().stream().map(TabBuilder.Placement::getItemId).collect(Collectors.toList());
	}

	static final String[] MAXED_MELEE = {
		"Torva full helm", "Torva platebody", "Torva platelegs", "Infernal cape", "Amulet of rancour", "Ferocious gloves",
		"Primordial boots", "Ultor ring", "Avernic defender", "Rada's blessing 4", "Scythe of Vitur", "Osmumten's fang",
		"Blade of Saeldor (c)", "Inquisitor's mace", "Abyssal tentacle", "Abyssal whip", "Dragon warhammer",
		"Bandos godsword", "Dragon claws", "Slayer helmet (i)", "Salve amulet(ei)", "Inquisitor's great helm",
		"Inquisitor's hauberk", "Inquisitor's plateskirt", "Neitiznot faceguard", "Bandos chestplate", "Bandos tassets",
		"Fire cape", "Barrows gloves", "Dragon defender", "Dragon hunter lance", "Ursine chainmace",
		"Super combat potion", "Saradomin brew", "Super restore", "Shark", "Anglerfish",
	};

	@Test
	public void maxedMeleeMainSet()
	{
		TabBuilder.Built built = build("melee", own(MAXED_MELEE));
		Map<String, Integer> main = bySlot(section(built, "main"));
		assertEquals(id("Torva full helm"), (int) main.get("HEAD"));
		assertEquals(id("Infernal cape"), (int) main.get("CAPE"));
		assertEquals(id("Amulet of rancour"), (int) main.get("AMULET"));
		assertNull("prayer bonus is situational: no blessing in the main set", main.get("AMMO"));
		assertTrue(items(section(built, "situational")).contains(id("Rada's blessing 4")));
		assertEquals(id("Scythe of Vitur"), (int) main.get("WEAPON"));
		assertEquals(id("Torva platebody"), (int) main.get("BODY"));
		assertEquals(id("Avernic defender"), (int) main.get("SHIELD"));
		assertEquals(id("Torva platelegs"), (int) main.get("LEGS"));
		assertEquals(id("Ferocious gloves"), (int) main.get("GLOVES"));
